/**
 * The `signature` grammar's parse tree: `name: Type = default`, the way
 * Python already spells a parameter —
 *
 *   pose: Pose = None
 *   window: int = 5
 *   temperature sensor readings          ← free text is a name, nothing else
 *
 * WHY one text field and not three boxes: a port on a whiteboard (or any
 * labelled slot) is a label first and a typed parameter second. Three boxes
 * impose the parameter's structure on someone who is only naming a thing,
 * while one line lets the structure appear exactly when it is typed — a `:`
 * makes a type, an `=` makes a default — and disappear when it is deleted.
 *
 * WHY depth-0 splitting: brackets and quotes are respected so
 * `dict[str, int]`, `Callable[[int], str] = f` and `lambda x: x` all land
 * in the slot they belong to, and a name may itself contain a space
 * (`chassis width: float`) without ambiguity — nobody names a slot with a
 * dict literal, so the first depth-0 `:` is unambiguously the type's.
 *
 * This module is pure parsing — no CodeMirror, no host. `signatureGrammar`
 * (in `signatureGrammar.ts`) turns it into a `CodeFieldGrammar`.
 */

export type SignatureSlot = "name" | "type" | "default";

export interface SignatureSpan {
  start: number;
  end: number;
}

export interface SignatureValue {
  name: string;
  type: string;
  defaultValue: string;
}

export interface ParsedSignature extends SignatureValue {
  /** Untrimmed character ranges of each slot in the source text. */
  spans: {
    name: SignatureSpan;
    colon: number | null;
    type: SignatureSpan | null;
    equals: number | null;
    default: SignatureSpan | null;
  };
}

interface SplitPoints {
  colon: number;
  equals: number;
}

/** The first depth-0 `:` (before any `=`) and the first depth-0 assignment `=`. */
function splitPoints(text: string): SplitPoints {
  let depth = 0;
  let quote: string | null = null;
  let colon = -1;
  let equals = -1;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index]!;
    if (quote) {
      if (char === "\\") index += 1;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      continue;
    }
    if (char === "(" || char === "[" || char === "{") {
      depth += 1;
      continue;
    }
    if (char === ")" || char === "]" || char === "}") {
      depth = Math.max(0, depth - 1);
      continue;
    }
    if (depth !== 0) continue;
    if (char === ":" && colon < 0 && text[index + 1] !== "=") {
      colon = index;
      continue;
    }
    if (char === "=") {
      const previous = text[index - 1] ?? "";
      const next = text[index + 1] ?? "";
      // `==`, `!=`, `<=`, `>=` are comparisons, `:=` is a walrus; only a
      // bare `=` is the default's assignment.
      if (next === "=" || "=!<>:".includes(previous)) continue;
      equals = index;
      break;
    }
  }
  return { colon, equals };
}

function trimmedSpan(text: string, start: number, end: number): SignatureSpan {
  let from = start;
  let to = end;
  while (from < to && /\s/.test(text[from]!)) from += 1;
  while (to > from && /\s/.test(text[to - 1]!)) to -= 1;
  return { start: from, end: to };
}

export function parseSignature(text: string): ParsedSignature {
  const { colon, equals } = splitPoints(text);
  const nameEnd = colon >= 0 ? colon : equals >= 0 ? equals : text.length;
  const typeEnd = equals >= 0 ? equals : text.length;
  const name = trimmedSpan(text, 0, nameEnd);
  const type = colon >= 0 ? trimmedSpan(text, colon + 1, typeEnd) : null;
  const defaultSpan = equals >= 0 ? trimmedSpan(text, equals + 1, text.length) : null;
  return {
    name: text.slice(name.start, name.end),
    type: type ? text.slice(type.start, type.end) : "",
    defaultValue: defaultSpan ? text.slice(defaultSpan.start, defaultSpan.end) : "",
    spans: {
      name,
      colon: colon >= 0 ? colon : null,
      type,
      equals: equals >= 0 ? equals : null,
      default: defaultSpan,
    },
  };
}

/** The canonical spelling of a `{ name, type, defaultValue }` triple. */
export function formatSignature(value: SignatureValue): string {
  const type = value.type ? `: ${value.type}` : "";
  const defaultValue = value.defaultValue ? ` = ${value.defaultValue}` : "";
  return `${value.name}${type}${defaultValue}`;
}

export interface SignatureSlotAt {
  slot: SignatureSlot;
  /** Where the slot's text begins — the point a completion replaces from. */
  start: number;
  end: number;
  /** The slot's text from its start to the caret, trimmed. */
  query: string;
}

/**
 * Which slot the caret is in. This is what makes the grammar grammar-aware:
 * the same keystroke offers types after a `:`, values after an `=`, and —
 * deliberately — nothing at all while a name is being typed.
 *
 * One signature is one line. Given a multi-line lane, the grammar is
 * applied to the caret's own line, with every offset reported against the
 * whole text so a completion can splice into the document directly.
 */
export function signatureSlotAt(text: string, caret: number): SignatureSlotAt {
  const at = Math.max(0, Math.min(caret, text.length));
  const lineStart = text.lastIndexOf("\n", at - 1) + 1;
  const nextBreak = text.indexOf("\n", at);
  const lineEnd = nextBreak === -1 ? text.length : nextBreak;
  const line = text.slice(lineStart, lineEnd);
  const local = at - lineStart;
  const { colon, equals } = splitPoints(line);
  const shift = (found: SignatureSlotAt): SignatureSlotAt => ({
    ...found,
    start: found.start + lineStart,
    end: found.end + lineStart,
  });
  if (equals >= 0 && local > equals) {
    const start = leadingSpaceEnd(line, equals + 1);
    return shift({ slot: "default", start, end: line.length, query: line.slice(start, local).trim() });
  }
  if (colon >= 0 && local > colon) {
    const start = leadingSpaceEnd(line, colon + 1);
    const end = equals >= 0 ? equals : line.length;
    return shift({ slot: "type", start, end, query: line.slice(start, Math.min(local, end)).trim() });
  }
  const end = colon >= 0 ? colon : equals >= 0 ? equals : line.length;
  return shift({ slot: "name", start: 0, end, query: line.slice(0, Math.min(local, end)).trim() });
}

/**
 * Every line of a lane parsed, with its spans shifted to whole-text
 * offsets. This is the parse the lane's decorations use — one call, all
 * lines — not a reconciler: turning these lines into a list of stored
 * objects (assigning ids, matching an edited line back to the record it
 * came from, handling insert/delete/reorder) is genuinely host-specific
 * and stays out of this package.
 */
export function parseSignatureLines(
  text: string,
): Array<ParsedSignature & { lineStart: number; lineEnd: number }> {
  const lines: Array<ParsedSignature & { lineStart: number; lineEnd: number }> = [];
  let lineStart = 0;
  for (const line of text.split("\n")) {
    const parsed = parseSignature(line);
    const shiftSpan = (span: SignatureSpan | null) =>
      span ? { start: span.start + lineStart, end: span.end + lineStart } : null;
    lines.push({
      ...parsed,
      spans: {
        name: shiftSpan(parsed.spans.name)!,
        colon: parsed.spans.colon === null ? null : parsed.spans.colon + lineStart,
        type: shiftSpan(parsed.spans.type),
        equals: parsed.spans.equals === null ? null : parsed.spans.equals + lineStart,
        default: shiftSpan(parsed.spans.default),
      },
      lineStart,
      lineEnd: lineStart + line.length,
    });
    lineStart += line.length + 1;
  }
  return lines;
}

function leadingSpaceEnd(text: string, from: number): number {
  let index = from;
  while (index < text.length && text[index] === " ") index += 1;
  return index;
}

/**
 * The patch a typed line means for a stored `{ name, type, defaultValue }`
 * triple, or `null` when it already says exactly this. An empty default
 * clears the key rather than storing `''`, so a value that never had one
 * stays byte-identical after a rename. This is the single-record half of
 * the write seam; reconciling several lane lines back into a list of
 * records with stable identity is the host's job (see `parseSignatureLines`).
 */
export function signaturePatch(
  current: SignatureValue,
  text: string,
): Partial<SignatureValue> | null {
  const parsed = parseSignature(text);
  const patch: Partial<SignatureValue> = {};
  if (parsed.name !== current.name) patch.name = parsed.name;
  if (parsed.type !== current.type) patch.type = parsed.type;
  if (parsed.defaultValue !== current.defaultValue) patch.defaultValue = parsed.defaultValue;
  return Object.keys(patch).length === 0 ? null : patch;
}

import { python } from "@codemirror/lang-python";
import type { Extension } from "@codemirror/state";

import type {
  CodeFieldCompletion,
  CodeFieldCompletionResult,
  CodeFieldDecorationRange,
  CodeFieldGrammar,
  CodeFieldLine,
  CodeFieldReference,
  CodeFieldSegment,
  CodeFieldSlotAt,
} from "./codeGrammar";
import { parseSignatureLines, signatureSlotAt } from "./signature";

export interface SignatureCompletionItem {
  label: string;
  detail?: string;
  /** CodeMirror's completion `type`, and the `completionBadge` lookup key (see `kindLabels`). Omit for no badge. */
  kind?: string;
}

export interface SignatureGrammarOptions {
  /** Offered after `:`, narrowed by CodeMirror's own match-as-you-type against what follows. */
  types?: readonly SignatureCompletionItem[];
  /** Offered after `=`. */
  values?: readonly SignatureCompletionItem[];
  /**
   * The language mounted for the default slot's own tokens (numbers,
   * strings, operators) — everything the three `bbox-sig-*` marks below
   * don't already colour. Pass `null` to mount none.
   */
  language?: Extension | null;
  /** See `CodeFieldGrammar.foldInactiveLinesAfter` — only meaningful on a multi-line lane. */
  foldInactiveLinesAfter?: number;
  /**
   * What a type name resolves to in the RENDERED tree: a click target
   * (`onJump`) and/or fields to show in place (`expandLines`). Omit to
   * render every type name as plain accent text with no reference
   * behaviour — the common case for a port line, which has nothing to
   * expand into.
   */
  resolveReference?(name: string): CodeFieldReference | null;
  /** Badge label per `SignatureCompletionItem.kind` (e.g. `{ "board-type": "board type" }`). Omit for no completion badges. */
  kindLabels?: Record<string, string>;
}

function decorate(text: string): CodeFieldDecorationRange[] {
  const ranges: CodeFieldDecorationRange[] = [];
  // One signature is one line; a lane is several — this walks every line so
  // the same grammar works whether `CodeField` is single-line or `multiline`.
  for (const { spans } of parseSignatureLines(text)) {
    if (spans.name.end > spans.name.start) {
      ranges.push({ from: spans.name.start, to: spans.name.end, className: "bbox-sig-name" });
    }
    if (spans.colon !== null) {
      ranges.push({ from: spans.colon, to: spans.colon + 1, className: "bbox-sig-punct" });
    }
    if (spans.type && spans.type.end > spans.type.start) {
      ranges.push({ from: spans.type.start, to: spans.type.end, className: "bbox-sig-type" });
    }
    if (spans.equals !== null) {
      ranges.push({ from: spans.equals, to: spans.equals + 1, className: "bbox-sig-punct" });
    }
    if (spans.default && spans.default.end > spans.default.start) {
      ranges.push({ from: spans.default.start, to: spans.default.end, className: "bbox-sig-default" });
    }
  }
  return ranges;
}

/**
 * The RENDERED-mode rows: one per line, split into the same three roles
 * `decorate` marks in source mode. Segments are sliced straight out of the
 * source (never a fabricated `": "` literal) so whatever spacing was
 * authored survives untouched — the gaps between captured spans (the
 * colon, the equals sign, any surrounding whitespace) become their own
 * `"punct"` segment rather than being silently dropped or normalised.
 */
function lines(text: string): CodeFieldLine[] {
  return parseSignatureLines(text).map((parsed, index) => {
    const { spans, lineStart, lineEnd } = parsed;
    const captured: Array<{ start: number; end: number; role: string; isReference?: boolean }> = [];
    if (spans.name.end > spans.name.start) {
      captured.push({ start: spans.name.start, end: spans.name.end, role: "name" });
    }
    if (spans.type && spans.type.end > spans.type.start) {
      captured.push({ start: spans.type.start, end: spans.type.end, role: "type", isReference: true });
    }
    if (spans.default && spans.default.end > spans.default.start) {
      captured.push({ start: spans.default.start, end: spans.default.end, role: "default" });
    }
    captured.sort((a, b) => a.start - b.start);
    const segments: CodeFieldSegment[] = [];
    let cursor = lineStart;
    for (const span of captured) {
      if (span.start > cursor) segments.push({ text: text.slice(cursor, span.start), role: "punct" });
      segments.push({ text: text.slice(span.start, span.end), role: span.role, isReference: span.isReference });
      cursor = span.end;
    }
    if (cursor < lineEnd) segments.push({ text: text.slice(cursor, lineEnd), role: "punct" });
    return { line: index, lineStart, indent: 0, segments };
  });
}

/** The identifier immediately before `pos` — where a value completion replaces from. */
function wordBefore(text: string, pos: number): { from: number; query: string } {
  let start = pos;
  while (start > 0 && /[A-Za-z0-9_]/.test(text[start - 1]!)) start -= 1;
  return { from: start, query: text.slice(start, pos) };
}

function toCompletions(items: readonly SignatureCompletionItem[]): CodeFieldCompletion[] {
  return items.map((item) => ({ label: item.label, detail: item.detail, type: item.kind }));
}

/**
 * One completion source, dispatched by slot. A name gets nothing — typing a
 * label must never be interrupted, and free text is a legal name. A `:`
 * offers `types`, narrowed as you type; an `=` offers `values`.
 *
 * WHY no completion for `name`: Zach's rule, carried over from the grammar
 * this was extracted from — a port (or any labelled slot) is a label
 * first, and a completion popup over ordinary prose reads as the field
 * correcting you.
 */
function complete(
  types: readonly SignatureCompletionItem[],
  values: readonly SignatureCompletionItem[],
) {
  return (
    slot: CodeFieldSlotAt | null,
    _query: string,
    ctx: { text: string; pos: number; explicit: boolean },
  ): CodeFieldCompletionResult | null => {
    if (!slot || slot.slot === "name") return null;
    if (slot.slot === "type") {
      if (types.length === 0) return null;
      return { from: slot.start, to: ctx.pos, options: toCompletions(types) };
    }
    if (values.length === 0) return null;
    const { from } = wordBefore(ctx.text, ctx.pos);
    return { from, to: ctx.pos, options: toCompletions(values) };
  };
}

/**
 * The `signature` grammar: `name: Type = default`. Ships with `CodeField`
 * as its first grammar — plug in `types`/`values` and you have a port row
 * or lane; add `resolveReference` and the same grammar drives a rendered
 * tree (a Type's own attribute body, say) with clickable/expandable type
 * names. The same `decorate`/`complete`/`lines`/`slotAt` work whether the
 * field holds one line or many.
 */
export function signatureGrammar(options: SignatureGrammarOptions = {}): CodeFieldGrammar {
  const {
    types = [],
    values = [],
    language,
    foldInactiveLinesAfter,
    resolveReference,
    kindLabels,
  } = options;
  return {
    language: language === null ? undefined : language ?? python(),
    slotAt: signatureSlotAt,
    decorate,
    complete: complete(types, values),
    foldInactiveLinesAfter,
    lines,
    resolveReference,
    completionBadge: kindLabels ? (type) => kindLabels[type] : undefined,
  };
}
